use super::KernelRule;

#[allow(clippy::too_many_lines)]
pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── D: dispatch — the never-materialize MoE weighted reduce
        // (prism #107). The MUL+VIEW×n+ADD×(n−1) subgraph folds into one
        // kernel; bit-identity is enforced against the compiler, not
        // hoped for; the dying weights get a staging rescue, x gets a
        // refusal.
        KernelRule {
            rule_id: "moe-router-weight-fold-into-reduce-never-materialize".to_string(),
            gpu_concept: "MECHANISM (the never-materialize consumer-fold into a reduction): a graph shape of MUL(broadcast-weight, x) followed by n per-slot VIEWs and (n−1) left-to-right ADDs — the MoE router-weighted expert reduce as build_moe_ffn emits it — folds into ONE kernel `dst[i0,i2] = sum_e x[i0,e,i2] * w[0,e,i2]`, so the weighted intermediate the MUL materializes is NEVER written or read. THE SOURCE LAW, verbatim (commit message): 'The mul writes a second full-size F32 tensor that only exists so the add chain can read it back; at large ubatch that is tens of MB written and read again per layer. The fused kernel folds the weighting into the reduction so the weighted intermediate is never materialized: only down_out streams in and the [n_embd, n_tokens] result streams out.' THE BIT-IDENTITY INSTRUMENT (the refusal that licenses the fusion), verbatim: 'GGML_OP_MUL rounds each product to F32 before storing it and the add chain folds left to right, so the kernel rounds every product (__fmul_rn) before accumulating (__fadd_rn) in increasing slot order; the explicit intrinsics keep nvcc from contracting a product and its accumulation into an FMA.' — and the kernel's own header: '__fmul_rn / __fadd_rn keep nvcc from contracting a product and its accumulation into an FMA, which would be more accurate but would not match the baseline.' A MORE-ACCURATE fast path is a WRONG fast path here: the fusion is only legal because the rounding ORDER is preserved (round-per-product, add in increasing slot order), and the test bound is 0.0 error against the unfused chain. THE DYING-OPERAND STAGING RESCUE, verbatim: 'The weights die at the mul, so the graph allocator routinely packs the add-chain output over them; rather than give up the fusion the op snapshots them into pool scratch (they are n_expert_used*n_tokens floats). An x/dst overlap still rejects the fusion.' — the aliasing law is a PAIR with opposite polarity: dst overlapping the weights → STAGE (a few KiB copy, the fusion survives; the snapshot is 'n_expert_used*n_tokens floats, a few KiB at typical shapes', taken via cudaMemcpyAsync into pool scratch BEFORE the reduce writes, with the staged strides sw1=1/sw2=n_exp); dst overlapping x → DECLINE (x is alive on the fused path's read side, a cross-block read/write race, no cheap repair). Why not the generic checker, verbatim: 'ggml_cuda_check_fusion_memory_ranges is not used here because it ignores sources whose op is GGML_OP_NONE and because it can only reject, while the weights case has a cheap repair.' THE ADMISSION (a shape-exact subgraph matcher, not an op-class guess): all-F32 + contiguous + same-shape mul/x; the weights must be per-(expert,token) scalars broadcast along ne0 ('if (w->ne[0] != 1 || w->ne[1] != n_exp || w->ne[2] != n_tok || w->ne[3] != 1)'); n_tok <= 65535 (one block row per token, grid.y limit); the n_exp VIEWs checked EXACT — view_src == mul, the slice geometry 'v->nb[0] != mul->nb[0] || v->nb[1] != mul->nb[2]' and '(const char *) v->data != (const char *) mul->data + e*mul->nb[1]'; the (n_exp−1) ADDs checked as the EXACT left-to-right chain ('expected_a = (k == 0) ? nodes[node_idx + 1] : nodes[node_idx + n_exp + k]' vs 'expected_b = nodes[node_idx + 2 + k]', pointer equality); the expert count caps at GGML_CUDA_MOE_REDUCE_MAX_EXPERTS 15 — 'bounded by ggml_can_fuse_subgraph's 32-node limit: the subgraph is 2*n_exp nodes' — 2..15 fuse by template switch, 16 falls through to the unfused ops. THE FLOAT4 ADMISSION is five-conjunct (ne0 % 4 == 0 && sx1 % 4 == 0 && sx2 % 4 == 0 && sd1 % 4 == 0 && both x and dst 16-byte POINTER-aligned) — a stride-aligned-yet-pointer-misaligned tensor takes the scalar kernel, never a misaligned vector load. KILL/DEBUG SWITCHES: 'GGML_CUDA_MOE_REDUCE_DISABLE=1 turns it off, parsed the same way as the GGML_CUDA_DISABLE_FUSION switch beside it in ggml_cuda_try_fuse.' and 'GGML_CUDA_MOE_REDUCE_DEBUG=1 logs each fusion, including whether the weights had to be staged.' THE TESTS (the bit-identity instrument, verbatim): 'MOE_WEIGHTED_REDUCE builds the same mul/view/add subgraph, expanding the views before the adds as build_moe_ffn does so the matcher sees the same node order, and compares the fused backend against the CPU reference at a 0.0 error bound to hold the kernel to its bit-identical claim. Cases cover expert counts 2, 3, 4, 8, 15 (the fusion cap) and 16 (must fall through to the unfused ops), the float4 and scalar element paths, single and multi-token rows, and weights as both a graph input and a dying in-graph intermediate.' Plus the aliasing layouts a generic harness cannot reach, verbatim: 'test-moe-weighted-reduce covers the two cases test-backend-ops cannot reach because it gives every tensor its own buffer. It places the tensors by hand in one buffer so that either the router weights sit inside dst's range (the fused op must detect this and stage them) or dst sits inside x's range (the fused op must decline), plus a no-overlap control, and compares each layout bit for bit against the CPU backend running the unfused ops.' And the harness validation: 'On Metal, which has no such fusion, all 48 cases pass at 0.0 against CPU, which validates the bound for the unfused chain.' — the no-fusion backend passing the same suite proves the TEST is honest, so the fused backend's 48/48 means something. MEASURED (A10, behavior matrix — NOT a wall-clock figure, never a bar): 'every no-overlap case fused with staged=0, every weights-inside-dst case fused with staged=1, every dst-inside-x case declined the fusion, with all 48 cases bit-identical to the CPU reference. GGML_CUDA_MOE_REDUCE_DISABLE=1 gave 0 fusions and 48/48 too.' DECISION CONTENT: (1) the fold eliminates a WRITE+READ round trip of a full-size intermediate, so the win GROWS with ubatch (tens of MB per layer) — bandwidth-class, not launch-count-class; (2) bit-identity is enforced AGAINST the compiler (explicit round-to-nearest intrinsics beat nvcc's contraction license) — the same shape as this corpus's contract-off/rounding-order laws but at the GRAPH-fusion site: the fusion must reproduce the UNFUSED rounding sequence, so the intrinsics are part of the mechanism, not polish; (3) the aliasing pair shows the dispatch-law polarity: overlap-with-something-dying is a STAGING problem (cheap repair, fuse anyway), overlap-with-something-alive is a REFUSAL (the race has no repair); (4) the shape-exact matcher (pointer-equality on the add chain, exact view strides/offsets) is what makes the kill switch honest — the fusion fires on THE shape build_moe_ffn emits, not on anything that looks like it; (5) the dead-weights precondition is itself load-bearing: staging is only correct because the weights have no other reader after the mul. ANTI-REGIME: a backend whose MUL does NOT round to F32 before storing (higher-precision intermediates) must NOT take this fusion's bit-identity claim; graphs where the weighted intermediate has ANOTHER consumer (the matcher's exact chain refuses by construction — never widen by guessing); expert counts past the subgraph-node cap fall through by design (the fallback is correct, just slower); x/dst overlap never stages (no repair exists). Distinct from fusion-residual-selected-by-identity-not-negation (B208 — WHICH operand may feed a fused residual, the admission-by-identity axis; THIS is the fold + its rounding law + its staging rescue), from producer-folds-single-consumer-family (entries_gpu_72 — the PRODUCER folded into the consumer's read when the output has no OTHER reader; HERE the intermediate HAS readers — the whole add chain — and the fold is ALGEBRAIC: the weighting multiplies INTO the reduction, deleting the intermediate by construction, not by reader-count elision; the two are opposite directions of never-materialize), from argmax-epilogue-replaces-output-materialization (entries_gpu_52 — top-k selected at the GEMM store site so [rows,V] is never written; same spirit, different site and no reduction fold, no aliasing law, no rounding-order refusal), from per-group-epilogue-deferred-between-mma-bursts (entries_gpu_67 — epilogue SCHEDULING between bursts, not a graph-level subgraph fold), and from hazard-tracked-aliasing-scratch-allocator (Batch 105 — the allocator TRACKS hazards; THIS is the consumer-side admission that classifies an allocator-caused overlap as stage-vs-decline). Source: PrismML-Eng/llama.cpp @ 930ddba3b7f07c1599354d2989aeb23b51988f91 (#107, the league fork's prism branch) -- ggml/src/ggml-cuda/ggml-cuda.cu (ggml_cuda_should_fuse_moe_weighted_reduce + the try_fuse arm + ggml_cuda_tensors_overlap), ggml/src/ggml-cuda/moe-reduce.cu (k_moe_weighted_reduce + the v4 arm + the staging block), ggml/src/ggml-cuda/moe-reduce.cuh (the cap + the contract comment), tests/test-moe-weighted-reduce.cpp (the 48-case bit-identity + aliasing suite), MIT. NotBenchable here (the A10 record is a behavior/admission matrix — fused/staged/declined as predicted, 48/48 bit-identical — and the traffic win is structural ('tens of MB written and read again per layer'), never a wall-clock bar; the 0.0-error bound IS the exactness instrument). Batch 220 / Plan 220. RIDER (Batch 242 / Plan 244 / Research 274 — ddalcu/mlx-serve @ 1015f7854fd8ee5c22e34993aaddee2443b9cfbf, MIT): the FRAMEWORK-DERIVED LADDER face — the explicit rounding sequence is TRANSCRIBED from the composed pair the fusion replaces, and what the pair does is a property of the FRAMEWORK, not of the math. The fused down + router-weighting + K-reduce, verbatim (transformer.zig:42778-42790): 'The decode expert tail ran down-gather -> score multiply -> sum over K as three dispatches, materializing a [K, hidden] intermediate between them. This kernel keeps the down projection's per-row arithmetic TEXTUALLY identical to `gatherQmv` (same GQMV_BODY_*, same lane-strided pack loop, same simd_sum tree, same T(acc) rounding — so each (slot, row) value is bit-identical to the unfused kernel's), parks the K per-row values in threadgroup memory, and finishes with the composed pair's exact semantics: per-slot product rounded to T (the elementwise `mlx_multiply`), then an ascending T accumulate over slots 0..K-1 (MLX's bf16 sum reduction accumulates in the INPUT dtype — the moeRouterTopK lesson). One dispatch replaces three, and the [K, hidden] round-trip never happens.' The ladder in code, verbatim (transformer.zig:42841-42851): 'slot_vals[slot * uint(ROWS) + r] = T(acc);' (the f32 dot rounds to T at the store) then '// Composed-pair replica: T-rounded per-slot product, ascending T sum.' over 'T total = T(0.0f);' ... 'T p = slot_vals[s2 * uint(ROWS) + lane] * scores[s2];' ... 'total = total + p;' — f32 accumulate -> round to T -> T-typed product -> ascending T-adds, in that order. THE AXIS vs this rule's CUDA instance: the Prism #107 kernel rounds every product to F32 (__fmul_rn) and accumulates in F32 left-to-right because GGML's MUL materializes F32 before the add chain reads it; the MLX instance rounds every product to T (bf16 — the elementwise multiply's output dtype) and accumulates the SUM in T ascending because MLX's bf16 sum reduction accumulates in the INPUT dtype — the SAME never-materialize fold with the OPPOSITE ladder, and the ladder is a transcription, not a design choice: whoever's composed ops the fusion deletes, their rounding semantics are inherited — read the framework's reduction-dtype law BEFORE writing the fused epilogue (the moeRouterTopK lesson is MLX's; this rule's F32 chain is ggml's; a third framework's is whatever its ops do). The staging is THREADGROUP ('parks the K per-row values in threadgroup memory' — slot_vals[TOPK*ROWS]), the intermediate elimination is this rule's own law ('the [K, hidden] round-trip never happens'), and the shared-expert epilogue carries the same transcription discipline, verbatim (moe_affine4.zig:95-96): 'The gated shared expert joins as the chain does it: sigmoid in T (MLX's Sigmoid op), the product rounded to T, the sum rounded to T.' Distinct from this rule's F32-rounding clause (round-per-product-in-F32 is the GGML member of the same law, not a universal — this rider is the T-typed member), from producer-folds-single-consumer-family (the algebraic-fold direction), and from bit-equal-fusion-mirrors-reference-reduction-regime (B242, entries_gpu_99 — the GEOMETRY mirror for norm-class ops; THIS is the weighted-reduce ladder and its framework-dtype dependence). Batch 242 rider. RIDER (Batch 265 external instance, vllm @ e4a676cd #61497 -- vllm/model_executor/layers/mamba/ops/ssd_state_passing.py): the OUTPUT-side slot-indexed write face — the producing kernel scatters straight into the consumer's cache slots named by an index tensor, so the materialized intermediate AND the host-side indexed scatter both vanish. The pre-fix shape was this rule's never-materialize target on the OUTPUT side: the SSD prefill materialized varlen_states (batch, nheads, headdim, dstate), returned it to host, then scattered — 'ssm_state[state_indices_tensor_p] = final_states' — a separate indexed-copy step per layer. The fix passes the cache tensor + the slot-per-sequence index INTO _state_passing_fwd_kernel (final_states_ptr + final_state_indices_ptr behind a HAS_FINAL_STATES constexpr), and each program writes its sequence's final state straight into its cache slot — verbatim (ssd_state_passing.py): 'Write this sequence's final state straight into its cache slot.' with the slot load 'slot = tl.load(final_state_indices_ptr + pid_b * stride_final_state_indices).to(tl.int64)' then 'tl.store(final_states_ptrs, states, mask=offs_m < dim)' — the consumer's ADDRESS is DATA (a slot index loaded in-kernel), never computed host-side; the wrapper's contract states the None shape, verbatim (ssd_combined.py docstring): 'varlen_states: (batch, nheads, headdim, dstate), or None if written', and the caller arms per path — 'final_states_out=None if has_checkpoints else ssm_state' + 'final_state_indices=None if has_checkpoints else state_indices_tensor_p' — so the host scatter survives ONLY under has_checkpoints, where the intermediate is genuinely multi-consumer. THE FALLBACK POSTURE disclosed, verbatim (ssd_combined.py): 'Implementations without the fused write (CPU) return the states.' — a producer that cannot fuse returns the states and the wrapper falls back to the same indexed copy ('final_states_out[final_state_indices] = varlen_states'), the caller seeing None either way: the fuse-or-fallback choice is invisible at the call site. TWO COMPANION FACES: (a) the JIT-variant control '@triton.jit(do_not_specialize_on_alignment=['final_state_indices_ptr'])' — the new index-pointer argument would otherwise fork compiled variants on alignment, multiplying the warmup/compile surface for a pointer whose alignment is not load-bearing; (b) the warmup widened to the FULL constexpr cross-product — verbatim (mamba_mixer2.py): 'Two kernels (_state_passing_fwd, _chunk_scan_fwd) use HAS_INITSTATES as a constexpr, and _state_passing_fwd also HAS_FINAL_STATES, producing separate compiled binaries. Warm up all code paths so none triggers JIT compilation during inference.' over 'itertools.product((False, True), repeat=2)' — every new constexpr axis multiplies the warmup grid, and a missed cell is a first-inference JIT stall. Source-reported (the PR body): 'Write prefill final states into ssm_state from the SSD scan when has_checkpoints is False (4 fewer launches per Mamba layer).' and the details row 'replacing the index casts, gather and `index_put`. The checkpoint path and CPU path are unchanged.' KINSHIP: the host rule owns the router-weight fold INTO a reduce — a COMPUTE-side intermediate deleted by algebra (the weighting multiplies into the reduction); THIS face owns the OUTPUT-side slot-indexed write — the RESULT lands in its consumer's cache slot at production, deleting the intermediate + the scatter step by address-as-data routing; the two compose (a fused reduce can write its result straight into consumer slots the same way), distinct axis. Batch 265 rider.".to_string(),
            ref_shape: "// naive: build_moe_ffn materializes the weighted expert outputs so\n// an add chain can fold them left to right — a full-size intermediate\n// written and read back per layer.\nstruct Graph {\n    nodes: Vec<Node>,\n}\n\nstruct Node {\n    op: Op,\n    data: *mut f32,\n    ne: [i64; 3],\n}\n\nenum Op {\n    Mul,\n    View(usize), // (src, byte offset)\n    Add,\n}\n\n// [n_embd, n_expert_used, n_tokens] experts tensor, then n views, then\n// the left-to-right add chain — the MUL's output is FULL-SIZE F32 and\n// exists only so the adds can read it back.\nfn build_moe_ffn_tail_naive(g: &mut Graph, down_out: Node, weights: Node, n_exp: usize) -> Node {\n    let experts = g.push_mul(down_out, weights); // tens of MB at large ubatch\n    let mut views = Vec::with_capacity(n_exp);\n    for e in 0..n_exp {\n        views.push(g.push_view(experts, e)); // one view per expert slot\n    }\n    let mut acc = views[0];\n    for v in &views[1..] {\n        acc = g.push_add(acc, *v); // folds LEFT TO RIGHT\n    }\n    acc\n}\n\n// the unfused runtime: two extra full-tensor passes per layer —\n// write the weighted intermediate, then read it back per add\nelementwise_mul(&mut experts, &down_out, &weights);\nfor v in &views {\n    elementwise_add(&mut moe_out, &moe_out, v);\n}".to_string(),
            opt_pattern: "// optimized: fold the weighting INTO the reduction — the weighted\n// intermediate is never materialized; the rounding SEQUENCE of the\n// unfused pair is preserved against the compiler (round per product,\n// add in increasing slot order, no FMA contraction); a dst/weights\n// overlap stages the dying weights into scratch, a dst/x overlap\n// declines.\nconst MAX_EXPERTS: usize = 15; // the subgraph is 2*n_exp nodes\n\nfn should_fuse(x: &Node, w: &Node, n_exp: usize, n_tok: i64) -> Result<bool, Decline> {\n    if n_exp < 2 || n_exp > MAX_EXPERTS {\n        return Ok(false); // 16 falls through to the unfused ops\n    }\n    if !is_f32(x) || !is_f32(w) || !contiguous(x) || !same_shape(mul, x) {\n        return Ok(false);\n    }\n    // the weights must be a per (expert, token) scalar broadcast along ne0\n    if w.ne[0] != 1 || w.ne[1] != n_exp as i64 || w.ne[2] != n_tok {\n        return Ok(false);\n    }\n    if n_tok > 65535 {\n        return Ok(false); // one block row per token (grid.y limit)\n    }\n    Ok(true)\n}\n\n// bit-identity is the contract: __fmul_rn per product, __fadd_rn\n// accumulating left to right — nvcc must NOT contract the FMA.\nfn fused_reduce_scalar(x: &[f32], w: &[f32], dst: &mut [f32], n_exp: usize) {\n    for i0 in 0..dst.len() {\n        let mut acc = mul_rn(x[i0], w[0]); // round EVERY product first\n        for e in 1..n_exp {\n            acc = add_rn(acc, mul_rn(x[i0 + e * stride_e], w[e])); // slot order\n        }\n        dst[i0] = acc;\n    }\n}\n\n// the aliasing pair: overlap-with-dying is a staging repair, overlap-\n// with-alive is a refusal.\nfn admit_aliasing(dst: &Node, x: &Node, w: &Node) -> Result<Option<Stage>, Decline> {\n    if tensors_overlap(dst, x) {\n        return Err(Decline::XOverlap); // cross-block race, no repair\n    }\n    if tensors_overlap(dst, w) {\n        // the weights die at the mul: snapshot them before the reduce\n        // writes — n_expert_used*n_tokens floats, a few KiB\n        let staged = pool_scratch_copy(w); // sw1=1, sw2=n_exp after copy\n        return Ok(Some(staged));\n    }\n    Ok(None)\n}\n\n// the float4 arm is five-conjunct: widths AND both pointers aligned —\n// stride-aligned-yet-pointer-misaligned takes the scalar kernel.\nfn use_v4(ne0: i64, sx1: i64, sx2: i64, sd1: i64, x: *const f32, d: *const f32) -> bool {\n    ne0 % 4 == 0 && sx1 % 4 == 0 && sx2 % 4 == 0 && sd1 % 4 == 0\n        && (x as usize) % 16 == 0 && (d as usize) % 16 == 0\n}".to_string(),
        },
    ]
}
